export const envelope = [64, 48, 64];

export default function build(api) {
  const W = api.size[0];
  const H = api.size[1];
  const D = api.size[2];
  const SEAT = 6;

  const darkPrismarine = "minecraft:dark_prismarine";
  const prismarine = "minecraft:prismarine";
  const deepslate = "minecraft:deepslate";
  const polishedDeepslate = "minecraft:polished_deepslate";
  const oxidizedCopper = "minecraft:oxidized_copper";
  const weatheredCopper = "minecraft:weathered_copper";
  const lightGrayConcrete = "minecraft:light_gray_concrete";
  const smoothQuartz = "minecraft:smooth_quartz";
  const polishedAndesite = "minecraft:polished_andesite";
  const stoneBricks = "minecraft:stone_bricks";
  const crackedStoneBricks = "minecraft:cracked_stone_bricks";
  const blackConcrete = "minecraft:black_concrete";
  const redConcrete = "minecraft:red_concrete";
  const orangeConcrete = "minecraft:orange_concrete";
  const quartzBlock = "minecraft:quartz_block";
  const cyanConcrete = "minecraft:cyan_concrete";
  const glowstone = "minecraft:glowstone";

  const cells = new Array(W * H * D);
  const groundColumns = new Uint8Array(W * D);

  function cellIndex(x, y, z) {
    return (y * D + z) * W + x;
  }

  function put(x, y, z, block, grounded) {
    const ix = Math.round(x);
    const iy = Math.round(y);
    const iz = Math.round(z);

    if (ix < 0 || ix >= W || iy < 0 || iy >= H || iz < 0 || iz >= D) {
      return;
    }

    cells[cellIndex(ix, iy, iz)] = block;
    if (grounded) {
      groundColumns[iz * W + ix] = 1;
    }
  }

  function box(x0, y0, z0, x1, y1, z1, block, grounded) {
    const minX = Math.max(0, Math.ceil(Math.min(x0, x1)));
    const maxX = Math.min(W - 1, Math.floor(Math.max(x0, x1)));
    const minY = Math.max(0, Math.ceil(Math.min(y0, y1)));
    const maxY = Math.min(H - 1, Math.floor(Math.max(y0, y1)));
    const minZ = Math.max(0, Math.ceil(Math.min(z0, z1)));
    const maxZ = Math.min(D - 1, Math.floor(Math.max(z0, z1)));

    for (let x = minX; x <= maxX; x += 1) {
      for (let y = minY; y <= maxY; y += 1) {
        for (let z = minZ; z <= maxZ; z += 1) {
          put(x, y, z, block, grounded);
        }
      }
    }
  }

  function ellipsoid(cx, cy, cz, rx, ry, rz, block, grounded) {
    const minX = Math.max(0, Math.ceil(cx - rx));
    const maxX = Math.min(W - 1, Math.floor(cx + rx));
    const minY = Math.max(0, Math.ceil(cy - ry));
    const maxY = Math.min(H - 1, Math.floor(cy + ry));
    const minZ = Math.max(0, Math.ceil(cz - rz));
    const maxZ = Math.min(D - 1, Math.floor(cz + rz));

    for (let x = minX; x <= maxX; x += 1) {
      const dx = (x - cx) / rx;
      const dx2 = dx * dx;
      if (dx2 > 1.0001) {
        continue;
      }

      for (let y = minY; y <= maxY; y += 1) {
        const dy = (y - cy) / ry;
        const partial = dx2 + dy * dy;
        if (partial > 1.0001) {
          continue;
        }

        for (let z = minZ; z <= maxZ; z += 1) {
          const dz = (z - cz) / rz;
          if (partial + dz * dz <= 1.0001) {
            const material = typeof block === "function"
              ? block(x, y, z)
              : block;
            put(x, y, z, material, grounded);
          }
        }
      }
    }
  }

  function tube(points, radii, block, grounded) {
    for (let i = 0; i < points.length - 1; i += 1) {
      const a = points[i];
      const b = points[i + 1];
      const dx = b[0] - a[0];
      const dy = b[1] - a[1];
      const dz = b[2] - a[2];
      const distance = Math.sqrt(dx * dx + dy * dy + dz * dz);
      const steps = Math.max(1, Math.ceil(distance * 2));

      for (let s = 0; s <= steps; s += 1) {
        const t = s / steps;
        const cx = a[0] + dx * t;
        const cy = a[1] + dy * t;
        const cz = a[2] + dz * t;
        const radius = radii[i] + (radii[i + 1] - radii[i]) * t;
        const verticalRadius = Math.max(1.75, radius * 0.72);

        ellipsoid(
          cx,
          cy,
          cz,
          radius,
          verticalRadius,
          radius,
          block,
          grounded
        );
      }
    }
  }

  function skin(x, y, z) {
    const n = (x * 37 + y * 17 + z * 23) % 41;
    if (y <= SEAT + 2 && n % 9 === 0) {
      return deepslate;
    }
    if (n === 1 || n === 8 || n === 27) {
      return prismarine;
    }
    return darkPrismarine;
  }

  function tentacleSkin(x, y, z) {
    const n = (x * 11 + y * 19 + z * 29) % 31;
    if (y <= SEAT + 1 && n % 7 === 0) {
      return deepslate;
    }
    if (n === 3 || n === 17) {
      return prismarine;
    }
    return darkPrismarine;
  }

  box(6, 6, 55, 57, 8, 57, lightGrayConcrete, true);
  box(7, 9, 55, 21, 10, 57, polishedAndesite, true);
  box(42, 9, 55, 56, 10, 57, polishedAndesite, true);
  box(24, 9, 55, 28, 11, 57, crackedStoneBricks, true);
  box(36, 9, 55, 41, 12, 57, crackedStoneBricks, true);

  box(19, 6, 3, 45, 6, 5, lightGrayConcrete, true);
  box(19, 6, 18, 45, 6, 20, lightGrayConcrete, true);
  box(19, 6, 5, 21, 6, 18, lightGrayConcrete, true);
  box(43, 6, 5, 45, 6, 18, lightGrayConcrete, true);

  box(27, 6, 4, 37, 7, 12, lightGrayConcrete, true);
  box(27, 6, 12, 37, 7, 18, lightGrayConcrete, true);
  box(29, 8, 6, 35, 8, 10, smoothQuartz, true);
  box(31, 8, 6, 33, 8, 10, polishedDeepslate, true);
  box(29, 8, 8, 35, 8, 8, polishedDeepslate, true);

  ellipsoid(31, 8, 42, 10, 2, 11, tentacleSkin, true);
  ellipsoid(31, 12, 42, 8, 6, 10, skin, true);
  ellipsoid(31, 16, 38, 8, 7, 9, skin, false);
  ellipsoid(32, 21, 33, 7, 7, 8, skin, false);
  ellipsoid(34, 26, 28, 7, 7, 7, skin, false);
  ellipsoid(35, 29, 21, 10, 8, 8, skin, false);

  ellipsoid(31, 10, 52, 5, 4, 8, skin, true);
  ellipsoid(31, 10, 59, 3, 3, 3, skin, true);
  ellipsoid(31, 8, 53, 8, 2, 5, tentacleSkin, true);

  tube(
    [
      [29, 11, 40],
      [24, 10, 36],
      [18, 9, 30],
      [12, 8, 23],
      [8, 8, 16],
      [6, 8, 10]
    ],
    [4, 3.8, 3.2, 2.8, 2.3, 1.8],
    tentacleSkin,
    true
  );

  tube(
    [
      [36, 11, 40],
      [42, 10, 36],
      [48, 9, 30],
      [54, 8, 23],
      [58, 8, 16],
      [60, 8, 10]
    ],
    [4, 3.8, 3.2, 2.8, 2.3, 1.8],
    tentacleSkin,
    true
  );

  tube(
    [
      [31, 10, 37],
      [28, 9, 31],
      [23, 8, 25],
      [19, 8, 18],
      [16, 8, 10]
    ],
    [4, 3.4, 2.8, 2.3, 1.8],
    tentacleSkin,
    true
  );

  tube(
    [
      [35, 10, 37],
      [39, 9, 31],
      [44, 8, 25],
      [49, 8, 18],
      [53, 8, 10]
    ],
    [4, 3.4, 2.8, 2.3, 1.8],
    tentacleSkin,
    true
  );

  ellipsoid(24, 17, 38, 5, 3, 6, oxidizedCopper, false);
  ellipsoid(38, 17, 38, 5, 3, 6, oxidizedCopper, false);
  ellipsoid(26, 23, 31, 3, 3, 5, prismarine, false);
  ellipsoid(40, 23, 31, 3, 3, 5, prismarine, false);

  box(28, 19, 44, 34, 23, 48, oxidizedCopper, false);
  box(27, 23, 39, 35, 28, 43, weatheredCopper, false);
  box(30, 28, 33, 36, 34, 37, oxidizedCopper, false);
  box(32, 33, 27, 37, 39, 31, oxidizedCopper, false);

  ellipsoid(35, 27, 14, 8, 4, 4, skin, false);
  ellipsoid(35, 23, 15, 7, 3, 3, deepslate, false);

  box(24, 22, 27, 27, 27, 30, cyanConcrete, false);
  box(41, 22, 27, 46, 27, 30, cyanConcrete, false);

  box(27, 31, 14, 33, 34, 17, oxidizedCopper, false);
  box(37, 31, 14, 43, 34, 17, oxidizedCopper, false);

  ellipsoid(27, 36, 20, 2, 4, 2, darkPrismarine, false);
  ellipsoid(43, 36, 20, 2, 4, 2, darkPrismarine, false);
  ellipsoid(35, 35, 24, 3, 3, 2, oxidizedCopper, false);

  box(28, 25, 10, 42, 27, 12, blackConcrete, false);
  box(30, 24, 9, 40, 24, 11, redConcrete, false);

  const teeth = [
    [30, 27, 9],
    [34, 27, 9],
    [38, 27, 9],
    [32, 23, 9],
    [36, 23, 9]
  ];

  for (let i = 0; i < teeth.length; i += 1) {
    put(teeth[i][0], teeth[i][1], teeth[i][2], quartzBlock, false);
  }

  box(27, 30, 12, 32, 34, 15, blackConcrete, false);
  box(38, 30, 12, 43, 34, 15, blackConcrete, false);

  put(30, 32, 11, glowstone, false);
  put(40, 32, 11, glowstone, false);
  put(29, 32, 11, orangeConcrete, false);
  put(31, 32, 11, orangeConcrete, false);
  put(39, 32, 11, orangeConcrete, false);
  put(41, 32, 11, orangeConcrete, false);

  ellipsoid(6, 8, 10, 2, 2, 2, oxidizedCopper, true);
  ellipsoid(60, 8, 10, 2, 2, 2, oxidizedCopper, true);
  ellipsoid(16, 8, 10, 2, 2, 2, oxidizedCopper, true);
  ellipsoid(53, 8, 10, 2, 2, 2, oxidizedCopper, true);

  put(18, 7, 30, glowstone, true);
  put(48, 7, 30, glowstone, true);
  put(23, 7, 25, glowstone, true);
  put(44, 7, 25, glowstone, true);

  for (let x = 0; x < W; x += 1) {
    for (let z = 0; z < D; z += 1) {
      if (groundColumns[z * W + x] === 0) {
        continue;
      }

      let terrainY = Math.floor(SEAT + api.heightAt(x, z));
      if (!Number.isFinite(terrainY)) {
        terrainY = SEAT;
      }
      if (terrainY < 0) {
        terrainY = 0;
      }
      if (terrainY >= H) {
        terrainY = H - 1;
      }

      let top = Math.max(SEAT - 1, terrainY - 1);
      if (top >= H) {
        top = H - 1;
      }

      for (let y = 0; y <= top; y += 1) {
        const i = cellIndex(x, y, z);
        if (cells[i] === undefined) {
          const pattern = (x * 13 + z * 7 + y * 5) % 17;
          if (y < SEAT - 1) {
            cells[i] = pattern === 0 ? deepslate : polishedDeepslate;
          } else {
            cells[i] = pattern < 4 ? stoneBricks : polishedAndesite;
          }
        }
      }
    }
  }

  for (let y = 0; y < H; y += 1) {
    for (let z = 0; z < D; z += 1) {
      for (let x = 0; x < W; x += 1) {
        const block = cells[cellIndex(x, y, z)];
        if (block !== undefined) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "Leviathan Breaker",
    seatY: SEAT,
    anchors: {
      pad: [32, 9, 8]
    }
  };
}
